package dev.industrialtechnology.test;
import java.util.*;import java.io.File;import java.nio.file.*;import java.nio.charset.StandardCharsets;import cpw.mods.fml.common.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiMainMenu;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.util.*;import net.minecraftforge.common.*;import net.minecraftforge.common.util.*;import org.lwjgl.opengl.GL11;import dev.industrialtechnology.core.*;
public final class LampClientChecks {
    private int phase,wait=30,age;private boolean done;private volatile boolean failed,ready;private final List<String> results=Collections.synchronizedList(new ArrayList<String>());private static int bx,by,bz;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private static WorldServer world(){return (WorldServer)player().worldObj;}
    private static void check(boolean b,String text){if(!b)throw new AssertionError(text);}
    private void server(String label,Runnable work){ServerWork.enqueue(()->{try{work.run();results.add("PASS: "+label);}catch(Throwable e){failed=true;results.add("FAIL: "+label+" :: "+e);IndustrialTechnology.log.error(label,e);}});}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent event){if(done||event.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{if(failed){finish();return;}
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=2;mc.gameSettings.renderDistanceChunks=4;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;mc.gameSettings.clouds=false;mc.launchIntegratedServer("retired-player","Removed content migration and lamp QA",null);phase=1;wait=70;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++age>120)throw new AssertionError("Old world join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);server("Player saved in the removed Moon dimension joins safely in the Overworld with diamond inventory and XP intact",()->{EntityPlayerMP p=player();WorldServer w=world();check(p.dimension==0&&p.getHealth()>0&&p.ridingEntity==null,"retired dimension login failed");ItemStack s=p.inventory.getStackInSlot(0);check(s!=null&&s.getItem()==Items.diamond&&s.stackSize==23&&p.experienceLevel==37,"retained inventory/XP changed");check(!DimensionManager.isDimensionRegistered(180)&&!DimensionManager.isDimensionRegistered(181),"space dimensions registered");});
            server("Real survival player places and toggles levers on all six retained lamp faces",()->{WorldServer w=world();EntityPlayerMP p=player();w.setWorldTime(18000);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");bx=(int)Math.floor(p.posX);bz=(int)Math.floor(p.posZ)+4;by=Math.max(70,w.getTopSolidOrLiquidBlock(bx,bz)+3);ItemStack diamond=p.inventory.mainInventory[0];
                for(ForgeDirection side:ForgeDirection.VALID_DIRECTIONS){int x=bx+side.ordinal()*3,y=by,z=bz;for(int cx=(x-20)>>4;cx<=(x+20)>>4;cx++)for(int cz=(z-20)>>4;cz<=(z+20)>>4;cz++)w.getChunkFromChunkCoords(cx,cz);w.setBlock(x,y-1,z,Blocks.stone,0,3);w.setBlock(x,y,z,ModRegistry.greenLamp,0,3);int lx=x+side.offsetX,ly=y+side.offsetY,lz=z+side.offsetZ;w.setBlockToAir(lx,ly,lz);p.setGameType(WorldSettings.GameType.SURVIVAL);p.playerNetServerHandler.setPlayerLocation(x+side.offsetX*3+1.5,y+side.offsetY*3,z+side.offsetZ*3+1.5,0,0);ItemStack lever=new ItemStack(Blocks.lever);p.inventory.currentItem=1;p.inventory.mainInventory[1]=lever;check(p.theItemInWorldManager.activateBlockOrUseItem(p,w,lever,x,y,z,side.ordinal(),.5f,.5f,.5f),"placement "+side);check(w.getBlock(lx,ly,lz)==Blocks.lever,"missing lever "+side+" at "+lx+","+ly+","+lz+" actual="+w.getBlock(lx,ly,lz)+" lamp="+w.getBlock(x,y,z)+" stack="+lever+" solid="+w.isSideSolid(x,y,z,side));Blocks.lever.onBlockActivated(w,lx,ly,lz,p,side.ordinal(),.5f,.5f,.5f);check(ModRegistry.greenLamp.getLightValue(w,x,y,z)==15,"no light "+side);Blocks.lever.onBlockActivated(w,lx,ly,lz,p,side.ordinal(),.5f,.5f,.5f);check(ModRegistry.greenLamp.getLightValue(w,x,y,z)==0&&w.getBlock(lx,ly,lz)==Blocks.lever,"off state detached lever "+side);if(side.ordinal()%2==1)Blocks.lever.onBlockActivated(w,lx,ly,lz,p,side.ordinal(),.5f,.5f,.5f);}
                p.inventory.currentItem=0;p.inventory.mainInventory[0]=diamond;p.inventory.mainInventory[1]=null;p.setGameType(WorldSettings.GameType.CREATIVE);p.capabilities.isFlying=true;p.sendPlayerAbilities();p.playerNetServerHandler.setPlayerLocation(bx+8,by+4,bz+12,180,14);ready=true;});phase=2;wait=60;return;}
        if(phase==2){if(!ready||mc.theWorld.getBlock(bx,by,bz)!=ModRegistry.greenLamp){if(++age>140)throw new AssertionError("Lamp chunks not ready");wait=10;return;}mc.gameSettings.hideGUI=true;phase=3;wait=35;return;}
        if(phase==3){check(mc.thePlayer.dimension==0,"client stayed in removed dimension");for(int i=0;i<6;i++)check(mc.theWorld.getBlock(bx+i*3,by,bz)==ModRegistry.greenLamp,"client lamp missing "+i);check(GL11.glGetError()==GL11.GL_NO_ERROR,"lamp render GL error");ScreenShotHelper.saveScreenshot(mc.mcDataDir,"retained-green-lamps-levers.png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());results.add("PASS: Client renders retained green lamps and attached levers with matching on/off states and no OpenGL error");finish();}
    }catch(Throwable e){failed=true;results.add("FAIL: client phase "+phase+" :: "+e);IndustrialTechnology.log.error("Lamp client QA",e);finish();}}
    private void finish(){if(done)return;done=true;try{results.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"lamp-client-report.txt").toPath(),String.join("\n",results).getBytes(StandardCharsets.UTF_8));}catch(Exception e){IndustrialTechnology.log.error("Lamp report",e);}Minecraft.getMinecraft().shutdown();}
}
